-- Généré par tests/build_guide.lua depuis GUIDE.ptBR.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.ptBR = {
    { "h1", "Guia do Panorama" },
    { "p", "Como usar o Panorama no WoW Forever e como configurar o HDR no Windows." },
    { "p", "|cffffd100Faça antes um backup das suas configurações.|r O Panorama altera configurações do jogo, e remover o addon não as desfaz. Antes de mudar qualquer coisa, feche o jogo e copie a pasta |cffffd100WTF|r da sua instalação do jogo para um lugar seguro. Para voltar atrás, feche o jogo e coloque essa cópia de volta no lugar." },
    { "h2", "1. Abrir a janela" },
    { "li", "Digite |cffffd100/pano|r, ou clique com o botão esquerdo no botão do Panorama no minimapa.", "-" },
    { "li", "Opções > AddOns > Panorama também tem um botão que a abre.", "-" },
    { "li", "Arraste a barra de título para mover a janela. Esc ou o botão de fechar a fecha.", "-" },
    { "p", "O botão do minimapa:" },
    { "li", "Clique esquerdo abre ou fecha a janela.", "-" },
    { "li", "Clique direito mostra as predefinições, o desfazer, o refazer e a reinicialização gráfica.", "-" },
    { "li", "Arraste-o para movê-lo ao redor do minimapa. |cffffd100/pano minimap|r o mostra ou oculta.", "-" },
    { "h2", "2. A janela" },
    { "row", "|cffffd100Simples|r, |cffffd100Avançado|r (ao lado do título)", "Simples: cada aba mostra uma lista curta das configurações principais, sem seções. Avançado: todas as configurações, por seção, com as regras por lugar e a seção Especialistas. Na primeira instalação fica Simples; se você já usava o Panorama, fica Avançado. A busca sempre encontra todas as configurações." },
    { "row", "Guia (canto superior direito)", "Abre este guia no jogo." },
    { "row", "Menu |cffffd100Opções|r (canto superior direito)", "|cffffd100Idioma|r (idioma do jogo ou um de dez idiomas; mudá-lo recarrega a interface), |cffffd100Aplicar a cada conexão|r, |cffffd100Botão do minimapa|r, |cffffd100Redefinir tudo…|r." },
    { "row", "|cffffd100Visual atual:|r (barra sob o título)", "O visual no mundo agora, e quem o define: você, Dia e noite ou o lugar. O botão dela (|cffffd100Editar|r, |cffffd100Editar esta regra|r) abre onde mudá-lo. Passe o mouse sobre a barra para ver qual vem primeiro." },
    { "row", "Abas", "|cffffd100Imagem|r (qualidade gráfica), |cffffd100HDR|r, |cffffd100Ambiente|r (visual do mundo), |cffffd100Meus filtros|r. A aba aberta é lembrada." },
    { "row", "Caixa de busca (à direita das abas)", "Digite uma palavra para listar as configurações correspondentes de todas as abas. Limpe-a para voltar." },
    { "row", "Predefinições (aba Imagem)", "Baixa, Média, Alta, Extra. A predefinição que combina com suas configurações fica destacada." },
    { "row", "Rodapé", "|cffffd100Desfazer|r cancela sua última alteração: controle deslizante, caixa, predefinição, filtro, ambiente ou Redefinir tudo. |cffffd100Refazer|r a recoloca. As últimas 20 alterações ficam guardadas até |cffffd100/reload|r. |cffffd100Reiniciar|r reinicia o motor gráfico." },
    { "p", "No modo Avançado, clique no título de uma seção para recolhê-la ou expandi-la. A seção |cffffd100Especialistas (só console)|r começa recolhida. O título de uma seção mostra quantas das suas configurações você mudou." },
    { "h3", "Uma linha de configuração" },
    { "li", "|cffffd100Controle deslizante|r: o valor é gravado quando você solta o botão do mouse, não enquanto arrasta.", "-" },
    { "li", "|cffffd100Caixa de valor|r ao lado do controle: digite um valor, depois pressione Enter ou clique em outro lugar. Esc cancela, Tab vai para a próxima caixa. A vírgula funciona como separador decimal. O valor fica dentro do intervalo do controle.", "-" },
    { "li", "|cffffd100Botão Padrão|r: devolve essa configuração ao valor padrão. Passe o mouse sobre ele para ver o valor.", "-" },
    { "li", "|cffffd100Marca dourada|r à esquerda: você mudou essa configuração.", "-" },
    { "li", "|cffffd100Menu do jogo|r: quando um menu do jogo também define esse valor, a ajuda do rótulo o cita. Esse menu não lê o valor de volta, então pode mostrar outro nível.", "-" },
    { "li", "|cffffd100Linha acinzentada|r: depende de outra configuração que está desligada (por exemplo, |cffffd100Qualidade da neblina volumétrica|r sem |cffffd100Neblina volumétrica|r, a intensidade da tonalidade sem tonalidade), ou um modo a define. Passe o mouse sobre o rótulo para ver o motivo. Uma linha que depende de outra fica deslocada para a direita, logo abaixo dela.", "-" },
    { "li", "Passe o mouse sobre um rótulo para ler a ajuda completa.", "-" },
    { "h2", "3. Predefinições" },
    { "row", "Baixa", "Desempenho máximo. Visão curta, sem sombras." },
    { "row", "Média", "Equilibrado. Bom desempenho e sombras razoáveis." },
    { "row", "Alta", "Nível Alto do jogo. Sombras completas, todos os efeitos." },
    { "row", "Extra", "Alta, com a maior distância de visão." },
    { "p", "As predefinições mudam apenas as configurações de qualidade gráfica da aba Imagem. Elas não mexem na câmera, no mouse, na interface, na nitidez, na baixa latência, no HDR nem nos filtros." },
    { "p", "Mudou de ideia? |cffffd100Desfazer|r (rodapé, ou |cffffd100/pano undo|r) restaura as configurações de antes da predefinição." },
    { "h2", "4. Ambiente" },
    { "p", "A aba Ambiente define o visual do mundo: efeitos sobre a imagem. Eles não mudam nenhuma configuração do jogo." },
    { "li", "|cffffd100Modo|r (topo da aba): |cffffd100Fixo|r (o mesmo filtro em todo lugar), |cffffd100Dia e noite|r (uma tonalidade diurna e uma noturna) ou |cffffd100Por lugar|r (veja abaixo). Fixo por padrão.", "-" },
    { "li", "|cffffd100Aqui|r: o lugar e a hora do dia detectados agora. Quando uma masmorra, um interior ou o clima vem antes de uma zona que você ajustou, ela indica isso.", "-" },
    { "li", "|cffffd100Filtro|r (modos Fixo e Dia e noite): |cffffd100Base|r usa as linhas abaixo. Um dos seus filtros (aba Meus filtros) substitui a tonalidade, a vinheta e a granulação, e traz o seu contraste, o seu brilho e a sua gama. |cffffd100Editar filtro|r o abre na aba Meus filtros.", "-" },
    { "li", "|cffffd100Tonalidade|r: clique em uma miniatura para aplicá-la na hora (sépia, quente, fria, noite, esmeralda, crepúsculo). |cffffd100Intensidade da tonalidade|r define a força.", "-" },
    { "li", "|cffffd100Vinheta|r: escurece as bordas da tela.", "-" },
    { "li", "|cffffd100Granulação|r: granulação animada.", "-" },
    { "li", "|cffffd100Tonalidade diurna|r e |cffffd100Tonalidade noturna|r (modo Dia e noite): o Panorama aplica a tonalidade diurna de dia e a tonalidade noturna à noite, segundo o dia e a noite do jogo. Elas substituem a tonalidade. A mudança é gradual das 19h às 21h e das 5h às 7h (horário do servidor). Um dos seus filtros escolhido na linha Filtro as substitui.", "-" },
    { "li", "|cffffd100Céu|r: as mesmas cores em gradiente, cheias no alto da tela e mais claras embaixo. |cffffd100Intensidade do céu|r define a força.", "-" },
    { "li", "|cffffd100Barras pretas|r: barras em cima e embaixo, de 0 a 20 % da tela cada uma, em todos os modos. O jogo ainda renderiza o que elas escondem, então não aumentam a taxa de quadros.", "-" },
    { "p", "No modo Simples, a aba mostra o modo, o lugar, o filtro, a tonalidade e sua intensidade, e as tonalidades diurna e noturna. Vinheta, granulação, céu e barras pretas ficam no modo Avançado." },
    { "h3", "Por lugar" },
    { "p", "No modo |cffffd100Por lugar|r, a tonalidade, o céu, a vinheta e a granulação mudam sozinhos, conforme o lugar onde você está." },
    { "li", "As linhas do modo Fixo ficam ocultas: a regra do lugar as substitui. Só as barras pretas permanecem. Os valores delas continuam salvos e voltam quando você muda o modo. No modo Simples, as regras fornecidas se aplicam; escolha Avançado para editá-las.", "-" },
    { "li", "|cffffd100Lugar|r: define o tom, a vinheta e a granulação. Ordem: masmorra ou raide, interior, clima (chuva, neve, tempestade de areia), depois o tipo de zona: terras temperadas, desertos e terras áridas, terras nevadas, selva e pântano, terras corrompidas, terras vulcânicas, florestas arcanas. Uma zona ainda desconhecida conta como temperada. O clima só conta quando Intensidade do clima é maior que 0.", "-" },
    { "li", "|cffffd100Hora do dia|r: define o céu (dia, amanhecer e entardecer, noite). A noite segue o dia e a noite do jogo; o amanhecer e o entardecer seguem a hora do servidor. Sem céu em interiores nem em masmorras.", "-" },
    { "li", "|cffffd100Regra|r (modo Avançado): escolha uma regra e ajuste-a abaixo. O botão Padrão devolve o valor fornecido para essa regra. Na primeira vez que a janela abre, a regra do lugar onde você está fica aberta. O menu tem cinco grupos: |cffffd100Zonas|r (a zona em que você está e as que você ajustou), |cffffd100Masmorra e interior|r, |cffffd100Clima|r, |cffffd100Tipo de zona|r e |cffffd100Céu (hora)|r. Os quatro primeiros ajustam o tom, a vinheta, a granulação e uma predefinição gráfica: só um lugar se aplica por vez, na ordem indicada acima. O último ajusta o céu. Não é preciso ajustar nada para começar: cada regra já tem seus valores.", "-" },
    { "li", "|cffffd100Esta zona|r: primeira opção do mesmo menu, com o nome da zona em que você está. Escolha-a para dar a esta zona seu próprio tom, vinheta e granulação, partindo do seu tipo de zona. Ela passa então antes do tipo de zona, mas depois de masmorra, interior e clima. As zonas que você ajusta continuam no menu. |cffffd100Voltar ao tipo de zona|r (ao lado do menu) remove os valores da zona: ela volta a seguir seu tipo de zona.", "-" },
    { "li", "|cffffd100Todas as zonas|r: submenu do mesmo menu, com todas as zonas conhecidas. Escolha uma para ajustá-la sem estar lá. As zonas são organizadas por continente.", "-" },
    { "li", "|cffffd100Predefinição|r e |cffffd100Distância do cenário|r (seção |cffffd100Imagem|r de um lugar ou de uma zona): elas se aplicam enquanto você está nesse lugar, por cima dos seus próprios ajustes, qualquer que seja o modo de ambiente. A distância do cenário do lugar vem antes da distância da predefinição. Seus próprios ajustes são mantidos e voltam quando você sai. |cffffd100Meus ajustes|r não muda nada. Exemplo: Baixa em masmorras, Extra em uma zona de que você gosta. Em uma masmorra ou raide, a primeira opção do menu ajusta só essa masmorra. Na aba Imagem, |cffffd100Aqui: …|r aparece ao lado das predefinições enquanto um lugar aplica as suas; no modo Avançado, ele abre essa regra. Em combate, a mudança espera o fim do combate.", "-" },
    { "li", "|cffffd100Filtro|r (primeira linha da seção |cffffd100Visual|r de um lugar ou de uma zona): esse lugar usa um dos seus filtros da aba Meus filtros, com o contraste, o brilho e a gama dele. |cffffd100Ajustes abaixo|r: a tonalidade, a vinheta e a granulação da regra. A seção Visual só se aplica no modo Por lugar.", "-" },
    { "h2", "5. Meus filtros" },
    { "p", "A aba Meus filtros permite criar quantos filtros seus você quiser. O filtro aberto aparece no mundo só como pré-visualização; o que vale é escolhido na aba Ambiente. |cffffd100Novo|r adiciona um e o abre, |cffffd100Excluir|r remove o filtro aberto: o filtro da aba Ambiente e as regras que o usavam voltam para nenhum filtro. Sempre resta um filtro." },
    { "li", "|cffffd100Filtro|r: escolhe o filtro que as linhas abaixo ajustam. |cffffd100Nome|r: dê um nome a ele (Enter para confirmar).", "-" },
    { "li", "|cffffd100Tonalidade|r: clique em uma miniatura para dar essa cor ao filtro. |cffffd100Vermelho|r, |cffffd100Verde|r, |cffffd100Azul|r (em %): a cor exata dele. |cffffd100Intensidade da tonalidade|r: a força dela.", "-" },
    { "li", "|cffffd100Vinheta|r e |cffffd100Granulação|r: as do filtro.", "-" },
    { "li", "|cffffd100Contraste|r, |cffffd100Brilho|r, |cffffd100Gama|r: ajustes de imagem que o filtro dá ao jogo enquanto está aplicado; depois voltam os seus próprios valores. Meus ajustes: nada muda. Dependendo do modo de exibição, podem não ter efeito.", "-" },
    { "li", "No modo Simples, a aba mostra só a tonalidade e a intensidade da tonalidade.", "-" },
    { "li", "Enquanto a aba está aberta, o filtro exibido aparece ao vivo no jogo. A barra |cffffd100Visual atual:|r indica quando é apenas uma prévia.", "-" },
    { "li", "Para usar um filtro: escolha-o na linha |cffffd100Filtro|r da aba Ambiente (modos Fixo e Dia e noite), ou de um lugar ou de uma zona (modo Por lugar). Ele substitui então a tonalidade, a vinheta e a granulação. |cffffd100Base|r ou |cffffd100Ajustes abaixo|r: nada muda.", "-" },
    { "h2", "6. Seus valores e o jogo" },
    { "li", "Na primeira instalação, o Panorama lê suas configurações atuais do jogo. Nada muda até você mexer em um controle.", "-" },
    { "li", "Uma mudança feita no menu Gráficos do jogo ou com |cffffd100/console|r aparece na janela.", "-" },
    { "li", "|cffffd100Aplicar a cada conexão|r (menu Opções, ligado por padrão): as configurações que você mudou no Panorama são gravadas de novo a cada conexão. As outras seguem o menu Gráficos do jogo.", "-" },
    { "li", "Uma mudança feita durante o combate é aplicada quando o combate termina.", "-" },
    { "li", "Algumas configurações, como o MSAA, exigem a reinicialização gráfica. Clique em |cffffd100Reiniciar|r no rodapé, ou digite |cffffd100/pano restart|r. A tela pisca por um segundo.", "-" },
    { "h2", "7. HDR no Windows" },
    { "p", "As configurações de HDR existem apenas como comandos de console no jogo. O Panorama as mostra na aba |cffffd100HDR|r. Você precisa de um monitor compatível com HDR." },
    { "h3", "Passo 1: ativar o HDR no Windows" },
    { "p", "Windows 11:" },
    { "li", "Abra |cffffd100Configurações > Sistema > Vídeo|r.", "1." },
    { "li", "Selecione o monitor HDR, se você tiver mais de um.", "2." },
    { "li", "Ative |cffffd100Usar HDR|r. O atalho |cffffd100Win + Alt + B|r também o liga ou desliga.", "3." },
    { "p", "Windows 10: |cffffd100Configurações > Sistema > Vídeo > Configurações de Cores HD do Windows|r (Windows HD Color settings), depois ative |cffffd100Reproduzir jogos e aplicativos em HDR|r (Play HDR games and apps)." },
    { "p", "Verifique também se o HDR está ativado no menu do próprio monitor, se ele tiver essa opção." },
    { "p", "Desative o |cffffd100HDR automático|r (Auto HDR) do Windows 11: |cffffd100Configurações > Sistema > Vídeo > HDR|r. Ele serve para jogos sem HDR. O WoW gera a própria imagem HDR." },
    { "h3", "Passo 2: descobrir o brilho de pico do seu monitor" },
    { "p", "Instale o aplicativo gratuito |cffffd100Calibragem HDR do Windows|r (Windows HDR Calibration) da Microsoft Store e execute-o. A luminância máxima que ele encontra é o brilho de pico do seu monitor, em nits." },
    { "p", "Sem o aplicativo, use a classificação HDR do monitor: DisplayHDR 400 significa cerca de 400 nits, DisplayHDR 600 cerca de 600, DisplayHDR 1000 cerca de 1000." },
    { "h3", "Passo 3: configurar o HDR no Panorama" },
    { "p", "Abra |cffffd100/pano|r, aba |cffffd100HDR|r. No modo Simples, a aba mostra só as três primeiras linhas abaixo: escolha |cffffd100Avançado|r para ver |cffffd100Intensidade HDR|r e o brilho de referência." },
    { "li", "Marque |cffffd100Saída HDR|r.", "1." },
    { "li", "Marque |cffffd100Usar brilho de pico|r ou |cffffd100Usar brilho de referência|r: um ou outro, nunca os dois. Sem um deles, a imagem fica escura.", "2." },
    { "p", "|cffffd100Modo de brilho de pico (recomendado)|r" },
    { "li", "Marque |cffffd100Usar brilho de pico|r.", "-" },
    { "li", "Defina |cffffd100Brilho de pico (nits)|r com o valor encontrado no passo 2.", "-" },
    { "li", "|cffffd100Intensidade HDR|r só funciona nesse modo. O padrão do jogo é 2. Mude-o em pequenos passos e compare: a Blizzard não documenta o efeito exato.", "-" },
    { "p", "|cffffd100Modo de brilho de referência|r" },
    { "li", "Marque |cffffd100Usar brilho de referência|r.", "-" },
    { "li", "|cffffd100Brilho de referência (nits)|r é o brilho do branco na cena. 203 é o valor padrão. Aumente-o se a imagem parecer escura demais em um ambiente claro. Intensidade HDR não tem efeito nesse modo.", "-" },
    { "p", "Se a imagem não mudar, clique em |cffffd100Reiniciar|r no rodapé." },
    { "h3", "Solução de problemas de HDR" },
    { "row", "Imagem muito escura", "Marque um dos dois modos de brilho." },
    { "row", "Imagem cinza ou desbotada", "Ative o HDR no Windows (passo 1) e no menu do monitor." },
    { "row", "HDR automático ligado no Windows", "Desative-o (passo 1)." },
    { "row", "Realces muito brilhantes ou achatados", "Defina o brilho de pico com o valor real do seu monitor (passo 2)." },
    { "row", "Você quer o HDR desligado", "Desmarque |cffffd100Saída HDR|r." },
    { "p", "Cada linha de HDR tem um botão Padrão que devolve o valor do jogo." },
    { "h2", "8. Comandos" },
    { "row", "|cffffd100/pano|r", "Abre ou fecha a janela" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Aplica uma predefinição" },
    { "row", "|cffffd100/pano undo|r", "Desfaz a última alteração" },
    { "row", "|cffffd100/pano redo|r", "Refaz a alteração que você acabou de desfazer" },
    { "row", "|cffffd100/pano reset|r", "Volta cada configuração e cada filtro ao padrão" },
    { "row", "|cffffd100/pano status|r", "Mostra no chat o lugar e o momento detectados e os filtros aplicados agora (durante uma transição, os valores de destino)" },
    { "row", "|cffffd100/pano apply|r", "Grava de novo as configurações mudadas no Panorama" },
    { "row", "|cffffd100/pano restart|r", "Reinicia o motor gráfico" },
    { "row", "|cffffd100/pano minimap|r", "Mostra ou oculta o botão do minimapa" },
    { "row", "|cffffd100/pano blackbars 10|r", "Faixas pretas a 10% da altura da tela (0 a 20). |cffffd100off|r as remove" },
    { "row", "|cffffd100/pano grain 10|r", "Granulação em 10 (0 a 100). |cffffd100off|r a remove" },
    { "row", "|cffffd100/pano vignette 10|r", "Vinheta em 10 (0 a 100). |cffffd100off|r a remove" },
    { "h2", "9. Redefinição" },
    { "li", "O botão |cffffd100Padrão|r de cada linha redefine essa configuração.", "-" },
    { "li", "O botão |cffffd100Padrões|r do menu Gráficos do jogo redefine apenas as configurações que esse menu gerencia, e o Panorama o acompanha. Use os botões Padrão em |cffffd100/pano|r para as outras e para os filtros.", "-" },
    { "li", "|cffffd100Redefinir tudo…|r (menu Opções, com confirmação) ou |cffffd100/pano reset|r: volta cada configuração alterada no Panorama e cada filtro ao padrão. |cffffd100Desfazer|r a cancela até |cffffd100/reload|r. A aba Ambiente e as zonas ajustadas também são redefinidas. Seus filtros da aba Meus filtros também são apagados.", "-" },
}
